command:
cat > /etc/nginx/conf.d/fleet-tls.conf <<'EOF'
server {
    listen 8443 ssl;
    server_name node2;

    ssl_certificate     /etc/pki/fleet-ca/node2.fullchain.pem;
    ssl_certificate_key /etc/pki/fleet-ca/node2.key.pem;
    ssl_protocols       TLSv1.2 TLSv1.3;

    location / {
        return 200 "node2 fleet-tls ok\n";
        add_header Content-Type text/plain;
    }
}
EOF
nginx -t

